1	using System.Globalization;
2	using System.Text.RegularExpressions;
3	using TutorFlow.Core.Academico;
4	using TutorFlow.Core.Autorizacion;
5	
6	namespace TutorFlow.Core.Asistente;
7	
8	internal sealed partial class DefinitivaPorAsignatura
9	{
10	    private const int PalabrasHastaLaCifra = 8;
11	    private const int PalabrasDelRequisito = 4;
12	    private const string Definitiva = "definitiva";
13	    private const string Definitivas = "definitivas";
14	
15	    private static readonly HashSet<string> Comparadores = new(StringComparer.Ordinal)
16	    {
17	        "menor", "mayor", "inferior", "superior", "minimo", "minima", "maximo", "maxima", "supera", "superar", "entre",
18	        "<", ">", "<=", ">="
19	    };
20	
21	    private static readonly HashSet<(string, string)> ComparadoresDeDosPalabras = new()
22	    {
23	        ("o", "igual"), ("al", "menos"), ("menos", "de"), ("mas", "de")
24	    };
25	
26	    private static readonly HashSet<string> Enlaces = new(StringComparer.Ordinal) { "a", "de", "que" };
27	
28	    private static readonly HashSet<string> Determinantes = new(StringComparer.Ordinal) { "una", "la" };
29	
30	    private static readonly HashSet<string> Negaciones = new(StringComparer.Ordinal) { "no", "ni", "sin" };
31	
32	    private static readonly HashSet<string>[] SaltosPrevios = [new(StringComparer.Ordinal) { "nota" }, Determinantes, FormasDePerdida.Auxiliares];
33	
34	    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;
35	
36	    public DefinitivaPorAsignatura(IReadOnlyList<AsignaturaCatalogo> catalogo)
37	    {
38	        _catalogo = catalogo;
39	    }
40	
41	    public string? Motivo(
42	        IReadOnlyList<BloqueDeTexto> bloques,
43	        Usuario usuario,
44	        IReadOnlyCollection<string> idsAutorizados,
45	        DirectorioAcademico directorio,
46	        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
47	    {
48	        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, directorio);
49	        return bloques
50	            .SelectMany(bloque => Atribuciones(bloque, catalogo).Select(atribucion => (Bloque: bloque, Atribucion: atribucion)))
51	            .Select(par => MotivoDe(par.Atribucion, TramosDePersonas.De(par.Bloque, usuario, idsAutorizados, directorio), usuario, directorio, resumenesLeidos))
52	            .FirstOrDefault(motivo => motivo is not null);
53	    }
54	
55	    public IEnumerable<(string Clave, string Cifra)> ParesDe(string respuesta, DirectorioAcademico directorio)
56	    {
57	        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, directorio);
58	        return BloquesDeRespuesta.De(respuesta).SelectMany(bloque =>
59	        {
60	            var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
61	            return Pares(bloque, tokens, CatalogoAsignaturas.Apariciones(tokens, catalogo), hayDefinitiva: true).Select(atribucion => (atribucion.Clave, atribucion.Cifra));
62	        });
63	    }
64	
65	    private static string? MotivoDe(
66	        AtribucionDeDefinitiva atribucion,
67	        PersonasDeBloque personas,
68	        Usuario usuario,
69	        DirectorioAcademico directorio,
70	        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
71	    {
72	        if (personas.Ambiguo)
73	        {
74	            return Motivo(atribucion, null, usuario, directorio);
75	        }
76	
77	        return personas.Tramos
78	            .Where(tramo => tramo.Tokens.Any(token => token.Inicio == atribucion.InicioDeAsignatura))
79	            .Where(tramo => !Coincide(atribucion, tramo.PersonaId, resumenesLeidos))
80	            .Select(tramo => Motivo(atribucion, tramo.PersonaId, usuario, directorio))
81	            .FirstOrDefault();
82	    }
83	
84	    private static string Motivo(AtribucionDeDefinitiva atribucion, string? personaId, Usuario usuario, DirectorioAcademico directorio)
85	    {
86	        var persona = personaId is null || usuario.Rol != Rol.Coordinador ? string.Empty : $" de {NombreDe(personaId, directorio)}";
87	        return $"la definitiva {atribucion.Cifra} de {atribucion.Escrita}{persona} no coincide con los datos entregados";
88	    }
89	
90	    private static string NombreDe(string personaId, DirectorioAcademico directorio) =>
91	        directorio.Estudiantes.Select(estudiante => (estudiante.Id, estudiante.Nombre))
92	            .Concat(directorio.Coordinadores.Select(coordinador => (coordinador.Id, coordinador.Nombre)))
93	            .FirstOrDefault(persona => persona.Id == personaId).Nombre ?? personaId;
94	
95	    private static IEnumerable<AtribucionDeDefinitiva> Atribuciones(BloqueDeTexto bloque, IReadOnlyList<AsignaturaCatalogo> catalogo)
96	    {
97	        var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
98	        var apariciones = CatalogoAsignaturas.Apariciones(tokens, catalogo);
99	        var hayDefinitiva = Enumerable.Range(0, tokens.Count).Any(indice => EsDefinitiva(tokens, indice) && !EstaNegada(tokens, indice));
100	        var porCifra = Enumerable.Range(0, tokens.Count)
101	            .Where(indice => tokens[indice].Valor == Definitiva && !EstaNegada(tokens, indice))
102	            .Select(indice => CifraEfectiva(tokens, indice))
103	            .OfType<int>()
104	            .SelectMany(cifra => AtribucionMasCercana(bloque, tokens, apariciones, cifra));
105	        return porCifra.Concat(Pares(bloque, tokens, apariciones, hayDefinitiva));
106	    }
107	
108	    private static IEnumerable<AtribucionDeDefinitiva> AtribucionMasCercana(
109	        BloqueDeTexto bloque,
110	        IReadOnlyList<TokenTexto> tokens,
111	        IReadOnlyList<AparicionDeAsignatura> apariciones,
112	        int cifra)
113	    {
114	        var asignatura = apariciones.MinBy(aparicion => (Distancia(aparicion, cifra), aparicion.Inicio > cifra));
115	        return asignatura is null ? [] : [Construir(bloque, tokens, asignatura, cifra, conDefinitiva: true)];
116	    }
117	
118	    private static IEnumerable<AtribucionDeDefinitiva> Pares(
119	        BloqueDeTexto bloque,
120	        IReadOnlyList<TokenTexto> tokens,
121	        IReadOnlyList<AparicionDeAsignatura> apariciones,
122	        bool hayDefinitiva) =>
123	        apariciones
124	            .Where(aparicion => aparicion.Fin + 1 < tokens.Count && EsCifraDeNota(tokens, aparicion.Fin + 1) && SoloSeparadores(bloque.Texto, tokens, aparicion))
125	            .Where(aparicion => !EsUmbralDeCifra(tokens, aparicion.Fin + 1))
126	            .Select(aparicion => Construir(bloque, tokens, aparicion, aparicion.Fin + 1, hayDefinitiva));
127	
128	    private static bool SoloSeparadores(string texto, IReadOnlyList<TokenTexto> tokens, AparicionDeAsignatura aparicion) =>
129	        SeparadoresDePar().IsMatch(texto[tokens[aparicion.Fin].Fin..tokens[aparicion.Fin + 1].Inicio]);
130	
131	    private static AtribucionDeDefinitiva Construir(
132	        BloqueDeTexto bloque,
133	        IReadOnlyList<TokenTexto> tokens,
134	        AparicionDeAsignatura asignatura,
135	        int cifra,
136	        bool conDefinitiva) =>
