4	namespace TutorFlow.Core.Asistente;
5	
6	internal static partial class LimpiezaDeOraciones
7	{
8	    private const int PalabrasMinimasPorOracion = 3;
9	    private const string EspacioEnBlanco = " ";
10	
11	    private static readonly TimeSpan LimiteRegex = TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos);
12	
13	    private static readonly (Regex Patron, string Reemplazo)[] ReglasDeSignos =
14	    [
15	        (new Regex(@"[\(\[][\s·,;:]*[\)\]]", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
16	        (new Regex(@" {2,}", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
17	        (new Regex(@"(?<!\d) +(?=[.,;:!?)])|(?<=\d) +(?=[;:!?)]|[.,](?!\d))", RegexOptions.CultureInvariant, LimiteRegex), string.Empty),
18	        (new Regex(@"(?<!\.)\.\.(?!\.)", RegexOptions.CultureInvariant, LimiteRegex), "."),
19	        (new Regex(@"[,;:]\.", RegexOptions.CultureInvariant, LimiteRegex), "."),
20	        (new Regex(@",,", RegexOptions.CultureInvariant, LimiteRegex), ","),
21	        (new Regex(@"^[\s:,;·]+", RegexOptions.CultureInvariant, LimiteRegex), string.Empty)
22	    ];
23	
24	    public static string Depurar(string marcada) =>
25	        string.Concat(CorteDeOracion().Split(marcada).Select(Oracion)).Trim();
26	
27	    private static string Oracion(string oracion) =>
28	        oracion.Contains(ReferenciasEscritas.Marca, StringComparison.Ordinal) ? Depurada(oracion) : oracion;
29	
30	    private static string Depurada(string marcada)
31	    {
32	        var texto = marcada.Replace(ReferenciasEscritas.Marca, ' ');
33	        if (TerminaEnAtribucionHuerfana(texto) || HuecoTrasPalabraIncompleta(marcada) || QuedaCorta(texto))
34	        {
35	            return string.Empty;
36	        }
37	
38	        var margen = EspaciosIniciales().Match(texto).Value;
39	        var cola = EspaciosFinales().Match(texto).Value;
40	        var cuerpo = ReglasDeSignos.Aggregate(texto.Trim(), (actual, regla) => regla.Patron.Replace(actual, regla.Reemplazo)).Trim();
41	        return margen + Capitalizar(cuerpo, marcada) + cola;
42	    }
43	
44	    private static bool TerminaEnAtribucionHuerfana(string texto) =>
45	        AtribucionHuerfana().IsMatch(PuntuacionFinal().Replace(texto, string.Empty));
46	
47	    private static bool HuecoTrasPalabraIncompleta(string marcada) =>
48	        Enumerable.Range(0, marcada.Length)
49	            .Where(indice => marcada[indice] == ReferenciasEscritas.Marca)
50	            .Any(indice => PalabraIncompleta().IsMatch(NormalizadorTexto.Normalizar(marcada[..indice]).TrimEnd()));
51	
52	    private static bool QuedaCorta(string texto) =>
53	        TerminaConPuntoFinal().IsMatch(texto.TrimEnd()) && PalabraOCifra().Count(texto) < PalabrasMinimasPorOracion;
54	
55	    private static string Capitalizar(string cuerpo, string marcada)
