38	    private readonly IBaseConocimiento _baseConocimiento;
39	    private readonly DefinitivaPorAsignatura _definitivas;
40	    private readonly PerdidaPorValor _perdida;
41	
42	    public CitasDeReglasAplicadas(IBaseConocimiento baseConocimiento, DefinitivaPorAsignatura definitivas)
43	    {
44	        _baseConocimiento = baseConocimiento;
45	        _definitivas = definitivas;
46	        _perdida = new PerdidaPorValor(definitivas);
47	    }
48	
49	    public IReadOnlyList<Cita> Usadas(RegistroConsultas registro, string respuesta, DirectorioAcademico directorio)
50	    {
51	        var texto = $" {NormalizadorTexto.Normalizar(respuesta)} ";
52	        return [.. registro.Reglas.Where(regla => UsaElCampo(regla, texto, respuesta, registro, directorio))];
53	    }
54	
55	    public IReadOnlyList<Cita> De(IReadOnlyList<Cita> usadas, string pregunta, IReadOnlyCollection<Cita> escritas) =>
56	        [.. Ordenar(usadas, RaicesDeContenido.De(pregunta).ToList()).Take(MaximoDeCitas).Where(regla => !escritas.Contains(regla))];
57	
58	    private List<Cita> Ordenar(IReadOnlyList<Cita> reglas, List<string> raices) =>
59	        raices.Count == 0 ? [.. reglas] : [.. reglas.OrderByDescending(regla => Relevancia(regla, raices))];
60	
61	    private int Relevancia(Cita regla, List<string> raices)
62	    {
63	        var seccion = _baseConocimiento.ObtenerSeccion(regla);
64	        var delaSeccion = seccion is null ? [] : RaicesDeContenido.De($"{seccion.Titulo} {seccion.Texto}").ToHashSet(StringComparer.Ordinal);
65	        return raices.Count(delaSeccion.Contains);
66	    }
67	
68	    private bool UsaElCampo(Cita regla, string texto, string respuesta, RegistroConsultas registro, DirectorioAcademico directorio) =>
69	        UsaUnTermino(regla, texto) || UsaElValor(regla, respuesta, registro, directorio);
70	
71	    private static bool UsaUnTermino(Cita regla, string texto) =>
72	        Terminos.TryGetValue(regla, out var palabras) && palabras.Any(palabra => texto.Contains($" {palabra} ", StringComparison.Ordinal));
73	
74	    private bool UsaElValor(Cita regla, string respuesta, RegistroConsultas registro, DirectorioAcademico directorio) =>
75	        (regla == Definitiva && ParPorValor(respuesta, registro, directorio))
76	        || (regla == Promedio && PromedioPorValor(respuesta, registro))
77	        || _perdida.Usa(regla, respuesta, registro, directorio);
78	
79	    private bool ParPorValor(string respuesta, RegistroConsultas registro, DirectorioAcademico directorio) =>
80	        registro.ReglasIncluyenNotas
81	        && _definitivas.ParesDe(respuesta, directorio).Any(par => registro.Resumenes.Values.Any(resumen => TieneDefinitiva(resumen, par)));
82	
83	    private static bool TieneDefinitiva(ResumenEstudiante resumen, (string Clave, string Cifra) par) =>
84	        resumen.Asignaturas.Any(resultado =>
85	            AmbitoPersonal.Clave(resultado.Asignatura.Codigo) == par.Clave
86	            && DefinitivaDe(resultado) == decimal.Parse(par.Cifra, CultureInfo.InvariantCulture));
87	
88	    private static decimal? DefinitivaDe(ResultadoAsignatura resultado) =>
89	        resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia ? 0m : resultado.Definitiva;
90	
91	    private static bool PromedioPorValor(string respuesta, RegistroConsultas registro)
92	    {
93	        var promedios = registro.Resumenes.Values.Where(resumen => resumen.Promedio is not null)
94	            .Select(resumen => resumen.Promedio!.Value.ToString("0.00", CultureInfo.InvariantCulture))
95	            .ToHashSet(StringComparer.Ordinal);
96	        return CifraConDosDecimales().Matches(TokenizadorTexto.Plegado(respuesta)).Any(cifra => promedios.Contains(cifra.Value));
97	    }
98	
99	    [GeneratedRegex(@"(?<![\d.])\d\.\d{2}(?!\d)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
100	    private static partial Regex CifraConDosDecimales();
101	}
