6	namespace TutorFlow.Core.Asistente;
7	
8	internal sealed partial class DefinitivaPorAsignatura
9	{
10	    private const int PalabrasHastaLaCifra = 8;
11	    private const int PalabrasDelRequisito = 4;
12	    private const string Definitiva = "definitiva";
13	    private const string Definitivas = "definitivas";
14	
15	    private static readonly HashSet<string> Comparadores = new(StringComparer.Ordinal)
16	    {
17	        "menor", "mayor", "inferior", "superior", "minimo", "minima", "maximo", "maxima", "supera", "superar", "entre",
18	        "<", ">", "<=", ">="
19	    };
20	
21	    private static readonly HashSet<(string, string)> ComparadoresDeDosPalabras = new()
22	    {
23	        ("o", "igual"), ("al", "menos"), ("menos", "de"), ("mas", "de")
24	    };
25	
26	    private static readonly HashSet<string> Enlaces = new(StringComparer.Ordinal) { "a", "de", "que" };
27	
28	    private static readonly HashSet<string> Determinantes = new(StringComparer.Ordinal) { "una", "la" };
29	
30	    private static readonly HashSet<string> Negaciones = new(StringComparer.Ordinal) { "no", "ni", "sin" };
31	
32	    private static readonly HashSet<string>[] SaltosPrevios = [new(StringComparer.Ordinal) { "nota" }, Determinantes, FormasDePerdida.Auxiliares];
33	
34	    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;
35	
36	    public DefinitivaPorAsignatura(IReadOnlyList<AsignaturaCatalogo> catalogo)
37	    {
38	        _catalogo = catalogo;
39	    }
40	
41	    public string? Motivo(
42	        IReadOnlyList<BloqueDeTexto> bloques,
43	        Usuario usuario,
44	        IReadOnlyCollection<string> idsAutorizados,
45	        DirectorioAcademico directorio,
46	        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
47	    {
48	        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, directorio);
49	        return bloques
50	            .SelectMany(bloque => Atribuciones(bloque, catalogo).Select(atribucion => (Bloque: bloque, Atribucion: atribucion)))
51	            .Select(par => MotivoDe(par.Atribucion, TramosDePersonas.De(par.Bloque, usuario, idsAutorizados, directorio), usuario, directorio, resumenesLeidos))
52	            .FirstOrDefault(motivo => motivo is not null);
53	    }
54	
55	    public IEnumerable<(string Clave, string Cifra)> ParesDe(string respuesta, DirectorioAcademico directorio)
56	    {
57	        var catalogo = CatalogoAsignaturas.Vigente(_catalogo, directorio);
58	        return BloquesDeRespuesta.De(respuesta).SelectMany(bloque =>
59	        {
60	            var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
61	            return Pares(bloque, tokens, CatalogoAsignaturas.Apariciones(tokens, catalogo), hayDefinitiva: true).Select(atribucion => (atribucion.Clave, atribucion.Cifra));
62	        });
63	    }
64	
65	    private static string? MotivoDe(
66	        AtribucionDeDefinitiva atribucion,
67	        PersonasDeBloque personas,
68	        Usuario usuario,
69	        DirectorioAcademico directorio,
70	        IReadOnlyDictionary<string, ResumenEstudiante> resumenesLeidos)
71	    {
72	        if (personas.Ambiguo)
73	        {
74	            return Motivo(atribucion, null, usuario, directorio);
75	        }
76	
77	        return personas.Tramos
78	            .Where(tramo => tramo.Tokens.Any(token => token.Inicio == atribucion.InicioDeAsignatura))
79	            .Where(tramo => !Coincide(atribucion, tramo.PersonaId, resumenesLeidos))
80	            .Select(tramo => Motivo(atribucion, tramo.PersonaId, usuario, directorio))
81	            .FirstOrDefault();
82	    }
