90	    private static string NombreDe(string personaId, DirectorioAcademico directorio) =>
91	        directorio.Estudiantes.Select(estudiante => (estudiante.Id, estudiante.Nombre))
92	            .Concat(directorio.Coordinadores.Select(coordinador => (coordinador.Id, coordinador.Nombre)))
93	            .FirstOrDefault(persona => persona.Id == personaId).Nombre ?? personaId;
94	
95	    private static IEnumerable<AtribucionDeDefinitiva> Atribuciones(BloqueDeTexto bloque, IReadOnlyList<AsignaturaCatalogo> catalogo)
96	    {
97	        var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
98	        var apariciones = CatalogoAsignaturas.Apariciones(tokens, catalogo);
99	        var hayDefinitiva = Enumerable.Range(0, tokens.Count).Any(indice => EsDefinitiva(tokens, indice) && !EstaNegada(tokens, indice));
100	        var porCifra = Enumerable.Range(0, tokens.Count)
101	            .Where(indice => tokens[indice].Valor == Definitiva && !EstaNegada(tokens, indice))
102	            .Select(indice => CifraEfectiva(tokens, indice))
103	            .OfType<int>()
104	            .SelectMany(cifra => AtribucionMasCercana(bloque, tokens, apariciones, cifra));
105	        return porCifra.Concat(Pares(bloque, tokens, apariciones, hayDefinitiva));
106	    }
107	
108	    private static IEnumerable<AtribucionDeDefinitiva> AtribucionMasCercana(
109	        BloqueDeTexto bloque,
110	        IReadOnlyList<TokenTexto> tokens,
111	        IReadOnlyList<AparicionDeAsignatura> apariciones,
112	        int cifra)
113	    {
114	        var asignatura = apariciones.MinBy(aparicion => (Distancia(aparicion, cifra), aparicion.Inicio > cifra));
115	        return asignatura is null ? [] : [Construir(bloque, tokens, asignatura, cifra, conDefinitiva: true)];
116	    }
117	
118	    private static IEnumerable<AtribucionDeDefinitiva> Pares(
119	        BloqueDeTexto bloque,
120	        IReadOnlyList<TokenTexto> tokens,
121	        IReadOnlyList<AparicionDeAsignatura> apariciones,
122	        bool hayDefinitiva) =>
123	        apariciones
124	            .Where(aparicion => aparicion.Fin + 1 < tokens.Count && EsCifraDeNota(tokens, aparicion.Fin + 1) && SoloSeparadores(bloque.Texto, tokens, aparicion))
125	            .Where(aparicion => !EsUmbralDeCifra(tokens, aparicion.Fin + 1))
126	            .Select(aparicion => Construir(bloque, tokens, aparicion, aparicion.Fin + 1, hayDefinitiva));
127	
128	    private static bool SoloSeparadores(string texto, IReadOnlyList<TokenTexto> tokens, AparicionDeAsignatura aparicion) =>
129	        SeparadoresDePar().IsMatch(texto[tokens[aparicion.Fin].Fin..tokens[aparicion.Fin + 1].Inicio]);
130	
131	    private static AtribucionDeDefinitiva Construir(
132	        BloqueDeTexto bloque,
133	        IReadOnlyList<TokenTexto> tokens,
134	        AparicionDeAsignatura asignatura,
135	        int cifra,
136	        bool conDefinitiva) =>
137	        new(
138	            asignatura.Clave,
139	            tokens[cifra].Valor,
140	            tokens[asignatura.Inicio].Inicio,
141	            bloque.Texto[tokens[asignatura.Inicio].Inicio..tokens[asignatura.Fin].Fin],
142	            conDefinitiva);
143	
144	    private static int Distancia(AparicionDeAsignatura asignatura, int cifra) =>
145	        asignatura.Fin < cifra ? cifra - asignatura.Fin : asignatura.Inicio - cifra;
146	
147	    private static bool EsDefinitiva(IReadOnlyList<TokenTexto> tokens, int indice) =>
148	        tokens[indice].Valor is Definitiva or Definitivas;
149	
150	    private static int? CifraEfectiva(IReadOnlyList<TokenTexto> tokens, int definitiva)
151	    {
152	        var cifra = CifraAsociada(tokens, definitiva);
153	        return cifra is { } asociada && EsUmbralDeCifra(tokens, asociada) ? SiguienteNoUmbral(tokens, asociada) : cifra;
154	    }
155	
156	    private static int? SiguienteNoUmbral(IReadOnlyList<TokenTexto> tokens, int desde) =>
157	        Enumerable.Range(desde + 1, Math.Max(0, tokens.Count - desde - 1))
158	            .Where(posicion => EsCifraDeNota(tokens, posicion) && !EsUmbralDeCifra(tokens, posicion))
159	            .Select(posicion => (int?)posicion)
160	            .FirstOrDefault();
161	
162	    private static bool EsUmbralDeCifra(IReadOnlyList<TokenTexto> tokens, int cifra) =>
163	        PrecedidaDeComparador(tokens, cifra) || SigueARequisito(tokens, cifra);
164	
165	    private static bool PrecedidaDeComparador(IReadOnlyList<TokenTexto> tokens, int cifra) =>
166	        TerminaComparador(tokens, cifra - 1) || (cifra > 0 && Enlaces.Contains(tokens[cifra - 1].Valor) && TerminaComparador(tokens, cifra - 2));
