168	    private static bool TerminaComparador(IReadOnlyList<TokenTexto> tokens, int indice) =>
169	        indice >= 0
170	        && (Comparadores.Contains(tokens[indice].Valor)
171	            || (indice > 0 && ComparadoresDeDosPalabras.Contains((tokens[indice - 1].Valor, tokens[indice].Valor))));
