177	    {
178	        var anterior = SaltosPrevios.Aggregate(indice - 1, (posicion, saltables) => Saltar(tokens, posicion, saltables));
179	        return anterior >= 0 && Negaciones.Contains(tokens[anterior].Valor);
180	    }
