135	            ? $"Perdida por inasistencia: {voz.Superaste} {maximo} inasistencias."
136	            : $"Si {voz.Supera} {maximo} inasistencias {voz.Pierde} la asignatura por inasistencia.";
137	        return $"{nombre}: faltas {faltas} de {clases} clases programadas (faltas restantes: {restantes}; máximo sin perder: {maximo}). {consecuencia}";
138	    }
